def transform(grid):
    result = [row[:] for row in grid]
    pattern_nums = [8, 5, 0, 7]

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:  # Marker
                # 8 at (mi-1, mj)
                if 0 <= i-1 < len(result):
                    result[i-1][j] = 8
                # 5 at (mi-1, mj+1)
                if 0 <= i-1 < len(result) and 0 < j+1 < len(result[0]):
                    result[i-1][j+1] = 5
                # 5 at (mi, mj+1)
                if 0 < j+1 < len(result[0]):
                    result[i][j+1] = 5
                # 0 at (mi, mj)
                result[i][j] = 0
                # 0 at (mi+1, mj-1)
                if 0 <= i+1 < len(result) and 0 <= j-1 < len(result[0]):
                    result[i+1][j-1] = 0
                # 7 at (mi+1, mj)
                if 0 <= i+1 < len(result):
                    result[i+1][j] = 7

    return result

