def transform_fixed(grid):
    result = [row[:] for row in grid]

    markers = [(i,j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == 1]

    for mi, mj in markers:
        result[mi-1][mj] = 8  # Above

    result[mi][mj] = 0    # Marker becomes 0
    result[mi+1][mj-1] = 0  # Down-left
    result[mi+1][mj] = 7   # Below
    result[mi-1][mj+1] = 5  # Up-right
    result[mi][mj+1] = 5    # Right

    return result

def transform_fixed_proper(grid):
    result = [row[:] for row in grid]

    markers = [(i,j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == 1]

    for mi, mj in markers:
        # 8 above
        if 0 <= mi-1 < len(result):
            result[mi-1][mj] = 8
        # Marker becomes 0
        result[mi][mj] = 0
        # 0 at down-left
        if 0 <= mi+1 < len(result) and 0 <= mj-1 < len(result[0]):
            result[mi+1][mj-1] = 0
        # 7 below
        if 0 <= mi+1 < len(result):
            result[mi+1][mj] = 7
        # 5 at up-right and right
        if 0 <= mi-1 < len(result) and 0 < mj+1 < len(result[0]):
            result[mi-1][mj+1] = 5
        if 0 < mj+1 < len(result[0]):
            result[mi][mj+1] = 5

    return result

