# I'll implement the transformation with spreading patterns.
# Based on my analysis:
# 8 at (mi-1, mj) spreads down-left: (mi-1-k, mj-k) for k>=0
# 5 at (mi-1, mj+1) spreads up-left: (mi-1-k, mj+1-k) for k>=0 ?
# 5 at (mi, mj+1) spreads...?

def transform_with_spread(grid):
    result = [row[:] for row in grid]

    markers = [(i,j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == 1]

    for mi, mj in markers:
        # 8 at (mi-1, mj) and spreads down-left along (mi-1-k, mj-k)
        for k in range(-4, 6):  # going UP toward canonical, then down
            ni, nj = mi - 1 - k, mj - k
            if 0 <= ni < len(result) and 0 <= nj < len(result[0]):
                if grid[ni][nj] != 1 and result[ni][nj] == 6:  # Background
                    result[ni][nj] = 8

        # 5 at (mi, mj+1) and spreads... up-right? 5 at (mi-k, mj+1+k)?
        for k in range(-8, 2):
            ni, nj = mi - k, mj + 1 + k
            if 0 <= ni < len(result) and 0 <= nj < len(result[0]):
                if grid[ni][nj] != 1 and result[ni][nj] == 6:
                    result[ni][nj] = 5

        # 0 at (mi, mj) and (mi+1, mj-1) and spreads down-left...
        for k in range(-3, 4):
            ni, nj = mi + k, mj - 1 - k
            if 0 <= ni < len(result) and 0 <= nj < len(result[0]):
                if grid[ni][nj] != 1 and result[ni][nj] == 6:
                    result[ni][nj] = 0

        # 7 at (mi+1, mj) spreads up-left?
        for k in range(-4, 6):
            ni, nj = mi + 1 + k, mj - k
            if 0 <= ni < len(result) and 0 <= nj < len(result[0]):
                if grid[ni][nj] != 1 and result[ni][nj] == 6:
                    result[ni][nj] = 7

    return result

